import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M15 1h-5v2H6V1H1c-.55 0-1 .45-1 1v11c0 .55.45 1 1 1h5v-2h4v2h5c.55 0 1-.45 1-1V2c0-.55-.45-1-1-1M4 13H2v-2h2zm0-3H2V8h2zm0-3H2V5h2zm0-3H2V2h2zm6 6H6V5h4zm4 3h-2v-2h2zm0-3h-2V8h2zm0-3h-2V5h2zm0-3h-2V2h2z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M19 2h-5v3H6V2H1c-.55 0-1 .45-1 1v14c0 .55.45 1 1 1h5v-3h8v3h5c.55 0 1-.45 1-1V3c0-.55-.45-1-1-1M4 17H2v-2h2zm0-3H2v-2h2zm0-3H2V9h2zm0-3H2V6h2zm0-3H2V3h2zm10 8H6V7h8zm4 4h-2v-2h2zm0-3h-2v-2h2zm0-3h-2V9h2zm0-3h-2V6h2zm0-3h-2V3h2z"] as readonly string[];

export const FilmIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="film" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
FilmIcon.displayName = `Blueprint6.Icon.FilmIcon`;

/**
 * @deprecated Use {@link FilmIcon} instead.
 */
export const Film: typeof FilmIcon = FilmIcon;

export default FilmIcon;
